'use strict';
// Exact Rack practice branch only. Empty owner-only installation, no authority.
const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');
const DISPATCH = path.join(__dirname,'reviewed-inputs/archive_dispatch_once_v2.sql');
const TICKET = path.join(__dirname,'reviewed-inputs/schedule_ticket_v1.sql');
const SOURCE = 'tzymapahsfiyhgilsmxl';
const PRINCIPAL = '02b550b8-b65c-481c-a8eb-495ab79242a6';
const sha = x => createHash('sha256').update(x).digest('hex');
const literal = x => "'" + String(x).replaceAll("'", "''") + "'";
const NEW_FUNCTIONS = [
  'rr_sandbox.archive_dispatch_no_reset_v2',
  'rr_sandbox.archive_dispatch_context_v2',
  'rr_sandbox.archive_claim_for_dispatch_v2',
  'rr_sandbox.archive_dispatch_consume_v2',
  'public.rr_test_archive_claim_for_dispatch_v2',
  'public.rr_test_archive_dispatch_consume_v2',
  'rr_sandbox.backup_schedule_ticket_no_reset_v1',
  'public.rr_test_backup_schedule_ticket_read_v1',
  'public.rr_test_backup_schedule_ticket_consume_v1'
];
const NEW_TABLES = ['rr_sandbox.archive_dispatch_once_v2', 'rr_sandbox.backup_schedule_ticket_v1'];
const eventsSQL = `SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.evtname,'event',e.evtevent,'enabled',e.evtenabled,'tags',e.evttags,'function',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')','function_md5',md5(pg_get_functiondef(e.evtfoid))) ORDER BY e.evtname),'[]'::jsonb) FROM pg_catalog.pg_event_trigger e JOIN pg_catalog.pg_proc p ON p.oid=e.evtfoid JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace`;
const functionsSQL = `SELECT coalesce(jsonb_agg(jsonb_build_object('oid',p.oid,'owner',p.proowner,'acl',p.proacl::text,'body',md5(pg_get_functiondef(p.oid))) ORDER BY p.oid),'[]'::jsonb) FROM pg_catalog.pg_proc p WHERE p.oid=ANY(old_functions)`;
const tablesSQL = `SELECT coalesce(jsonb_agg(jsonb_build_object('oid',c.oid,'owner',c.relowner,'acl',c.relacl::text,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity) ORDER BY c.oid),'[]'::jsonb) FROM pg_catalog.pg_class c WHERE c.oid=ANY(old_tables)`;
const policiesSQL = `SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_catalog.pg_policy p WHERE p.polrelid=ANY(old_tables)`;
const triggersSQL = `SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_catalog.pg_trigger t WHERE t.oid=ANY(old_triggers)`;
const defaultsSQL = `SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.oid),'[]'::jsonb) FROM pg_catalog.pg_default_acl d`;
function build(pin) {
  if (pin?.sourceProject !== SOURCE || pin.install_actor !== 'postgres' || pin.private_schema_owner !== 'postgres' ||
      !/^1[78]\d{4}$/.test(pin.server_version_num) || !Array.isArray(pin.event_triggers) ||
      pin.dedicated_machine?.id !== PRINCIPAL || pin.dedicated_machine.confirmed !== true || pin.dedicated_machine.active !== true ||
      pin.source_bucket?.id !== 'listing-photos' || pin.source_bucket.public !== false ||
      pin.old_archive_entries?.total !== 0 || pin.old_archive_entries.unknown !== 0 || pin.old_archive_entries.verified !== 0 ||
      !Array.isArray(pin.catalogue?.routines)) throw Error('CLOSED_ADMISSION_PIN_HELD');
  let dispatch = fs.readFileSync(DISPATCH, 'utf8'), ticket = fs.readFileSync(TICKET, 'utf8');
  if (sha(dispatch) !== 'd3a58a032f41c67117f31cdabadfb5ccf8704535a87f5f72363b45d54bf7c3e2' ||
      sha(ticket) !== '097aea882ec2c2a7f8109aba4c6d4b46105635cda44d88f4ddc7b357155021b5') throw Error('REVIEWED_SQL_BYTES_CHANGED');
  // Preserve reviewed routine bodies. This closed stage removes only the four
  // proposed service-role grants and its standalone transaction delimiters.
  dispatch = dispatch.replace(/^BEGIN;\s*$/m, '').replace(/^COMMIT;\s*$/m, '');
  const grant = /GRANT EXECUTE ON FUNCTION[\s\S]+?TO service_role;\s*$/;
  if (!grant.test(dispatch)) throw Error('DISPATCH_GRANT_SHAPE_HELD');
  dispatch = dispatch.replace(grant, '');
  const fnNames = 'ARRAY[' + NEW_FUNCTIONS.map(literal).join(',') + ']';
  const tableNames = 'ARRAY[' + NEW_TABLES.map(literal).join(',') + ']';
  const legacyPins = pin.catalogue.routines.filter(x => x.schema === 'rr_sandbox' && x.name.startsWith('archive_write_'));
  if (legacyPins.length !== 6 || legacyPins.some(x => !/^[a-f0-9]{32}$/.test(x.body_md5))) throw Error('LEGACY_JOURNAL_PIN_HELD');
  const legacyChecks = legacyPins.map(x => `IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='rr_sandbox' AND p.proname=${literal(x.name)} AND md5(pg_get_functiondef(p.oid))=${literal(x.body_md5)}) THEN RAISE EXCEPTION 'LEGACY_JOURNAL_CHANGED'; END IF;`).join('\n');
  const expectedEvents = literal(JSON.stringify(pin.event_triggers));
  return `-- Rack practice project ${SOURCE}. One atomic, closed, EMPTY installation.\n` +
`DO $rr_closed_admission$
DECLARE
 prior_path text:=current_setting('search_path');
 old_functions oid[]; old_tables oid[]; old_triggers oid[];
 before_functions jsonb; before_tables jsonb; before_policies jsonb; before_triggers jsonb; before_defaults jsonb;
 before_guard jsonb; before_entries jsonb; observed jsonb;
 actor text; fn regprocedure; target regclass;
 new_function_names text[]:=${fnNames}; new_table_names text[]:=${tableNames};
BEGIN
 PERFORM set_config('search_path','pg_catalog',true);
 IF current_user<>'postgres' OR current_setting('server_version_num')<>${literal(pin.server_version_num)}
  OR (SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='rr_sandbox') IS DISTINCT FROM 'postgres'
  OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id='${PRINCIPAL}' AND email='rack-photo-backup-20261127@example.invalid' AND email_confirmed_at IS NOT NULL AND NOT is_anonymous AND (banned_until IS NULL OR banned_until<now()))
  OR NOT EXISTS(SELECT 1 FROM storage.buckets WHERE id='listing-photos' AND NOT public AND file_size_limit=2097152 AND allowed_mime_types=ARRAY['image/png']::text[])
  OR NOT EXISTS(SELECT 1 FROM pg_db_role_setting s JOIN pg_roles r ON r.oid=s.setrole WHERE r.rolname='authenticator' AND 'pgrst.db_pre_request=public.rr_backup_source_data_api_boundary'=ANY(s.setconfig))
 THEN RAISE EXCEPTION 'CLOSED_ADMISSION_EXACT_TARGET_HELD'; END IF;
 SELECT (${eventsSQL}) INTO observed;
 IF observed IS DISTINCT FROM ${expectedEvents}::jsonb THEN RAISE EXCEPTION 'EVENT_INVENTORY_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(new_table_names) t WHERE to_regclass(t) IS NOT NULL)
  OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=ANY(new_function_names))
 THEN RAISE EXCEPTION 'CLOSED_ADMISSION_ALREADY_PRESENT'; END IF;
 ${legacyChecks}
 IF EXISTS(SELECT 1 FROM rr_sandbox.archive_write_entries) OR
  (SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY singleton),'[]'::jsonb) FROM rr_sandbox.archive_write_guard g) IS DISTINCT FROM '[{"revision":0,"singleton":true,"archive_identity":null}]'::jsonb
 THEN RAISE EXCEPTION 'LEGACY_ARCHIVE_STATE_CHANGED'; END IF;
 SELECT array_agg(p.oid) INTO old_functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND n.nspname IN('public','rr_sandbox');
 SELECT array_agg(c.oid) INTO old_tables FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname IN('public','rr_sandbox');
 SELECT array_agg(t.oid) INTO old_triggers FROM pg_trigger t WHERE t.tgrelid=ANY(old_tables);
 SELECT (${functionsSQL}) INTO before_functions;
 SELECT (${tablesSQL}) INTO before_tables;
 SELECT (${policiesSQL}) INTO before_policies;
 SELECT (${triggersSQL}) INTO before_triggers;
 SELECT (${defaultsSQL}) INTO before_defaults;
 SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY singleton),'[]'::jsonb) INTO before_guard FROM rr_sandbox.archive_write_guard g;
 SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY object_key),'[]'::jsonb) INTO before_entries FROM rr_sandbox.archive_write_entries e;

 EXECUTE $dispatch_payload$${dispatch}$dispatch_payload$;
 EXECUTE $ticket_payload$${ticket}$ticket_payload$;

 IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=ANY(new_function_names))<>9
  OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace, LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname||'.'||p.proname=ANY(new_function_names) AND a.grantee<>p.proowner)
  OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace, LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname||'.'||c.relname=ANY(new_table_names) AND (a.grantee<>c.relowner OR NOT c.relrowsecurity))
 THEN RAISE EXCEPTION 'CLOSED_ADMISSION_OWNER_ONLY_HELD'; END IF;
 FOR actor IN SELECT unnest(ARRAY['anon','authenticated','service_role']) LOOP
  FOR fn IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=ANY(new_function_names) LOOP
   IF has_function_privilege(actor,fn,'EXECUTE') THEN RAISE EXCEPTION 'CLOSED_ADMISSION_EFFECTIVE_ACL_HELD'; END IF;
  END LOOP;
  FOREACH target IN ARRAY ARRAY['rr_sandbox.archive_dispatch_once_v2'::regclass,'rr_sandbox.backup_schedule_ticket_v1'::regclass] LOOP
   IF has_table_privilege(actor,target,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') THEN RAISE EXCEPTION 'CLOSED_ADMISSION_EFFECTIVE_ACL_HELD'; END IF;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM rr_sandbox.archive_dispatch_once_v2) OR EXISTS(SELECT 1 FROM rr_sandbox.backup_schedule_ticket_v1) THEN RAISE EXCEPTION 'CLOSED_ADMISSION_NOT_EMPTY'; END IF;
 IF (${functionsSQL}) IS DISTINCT FROM before_functions OR (${tablesSQL}) IS DISTINCT FROM before_tables
  OR (${policiesSQL}) IS DISTINCT FROM before_policies OR (${triggersSQL}) IS DISTINCT FROM before_triggers
  OR (${defaultsSQL}) IS DISTINCT FROM before_defaults
  OR (SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY singleton),'[]'::jsonb) FROM rr_sandbox.archive_write_guard g) IS DISTINCT FROM before_guard
  OR (SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY object_key),'[]'::jsonb) FROM rr_sandbox.archive_write_entries e) IS DISTINCT FROM before_entries
  OR (${eventsSQL}) IS DISTINCT FROM ${expectedEvents}::jsonb
 THEN RAISE EXCEPTION 'EXISTING_OBJECT_OR_ARCHIVE_CHANGED'; END IF;
 PERFORM set_config('search_path',prior_path,true);
END $rr_closed_admission$;
`;
}
function rollback() {
 const names='ARRAY['+NEW_FUNCTIONS.map(literal).join(',')+']';
 return `-- Exact empty closed Rack practice additions only; no CASCADE or record deletion.
DO $rr_closed_admission_rollback$
DECLARE r record; names text[]:=${names};
BEGIN
 IF current_user<>'postgres' OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id='${PRINCIPAL}' AND email='rack-photo-backup-20261127@example.invalid')
  OR to_regclass('rr_sandbox.archive_dispatch_once_v2') IS NULL OR to_regclass('rr_sandbox.backup_schedule_ticket_v1') IS NULL
 THEN RAISE EXCEPTION 'EMPTY_ADMISSION_ROLLBACK_TARGET_HELD'; END IF;
 IF EXISTS(SELECT 1 FROM rr_sandbox.archive_dispatch_once_v2) OR EXISTS(SELECT 1 FROM rr_sandbox.backup_schedule_ticket_v1)
  OR (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=ANY(names))<>9
 THEN RAISE EXCEPTION 'EMPTY_ADMISSION_ROLLBACK_STATE_HELD'; END IF;
 DROP TABLE rr_sandbox.backup_schedule_ticket_v1;
 DROP TABLE rr_sandbox.archive_dispatch_once_v2;
 FOR r IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=ANY(names) ORDER BY (n.nspname='public') DESC,p.oid DESC LOOP
  EXECUTE format('DROP FUNCTION %s',r.oid::regprocedure);
 END LOOP;
END $rr_closed_admission_rollback$;\n`;
}
module.exports = { build, rollback, NEW_FUNCTIONS, NEW_TABLES, SOURCE, PRINCIPAL, eventsSQL };

'use strict';
const test=require('node:test'), assert=require('node:assert/strict');
const fs=require('node:fs');
const {PGlite}=require('@electric-sql/pglite');
const {build,rollback,PRINCIPAL,NEW_FUNCTIONS,eventsSQL}=require('./closed-install.cjs');
const ROOT=__dirname+'/reviewed-inputs/';
const managed=JSON.parse(fs.readFileSync(__dirname+'/fixture-pin.json','utf8'));
async function fixture(){
 const db=new PGlite();
 await db.exec(`CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role; CREATE ROLE authenticator;
 CREATE SCHEMA rr_sandbox; CREATE SCHEMA auth; CREATE SCHEMA storage;
 CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz,is_anonymous boolean,banned_until timestamptz);
 INSERT INTO auth.users VALUES('${PRINCIPAL}','rack-photo-backup-20261127@example.invalid',now(),false,null);
 CREATE TABLE storage.buckets(id text PRIMARY KEY,public boolean,file_size_limit bigint,allowed_mime_types text[]);
 INSERT INTO storage.buckets VALUES('listing-photos',false,2097152,ARRAY['image/png']);
 CREATE FUNCTION public.rr_backup_source_data_api_boundary() RETURNS void LANGUAGE plpgsql AS $$BEGIN RETURN;END$$;
 ALTER ROLE authenticator SET pgrst.db_pre_request='public.rr_backup_source_data_api_boundary';
 ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO anon,authenticated,service_role;`);
 await db.exec(fs.readFileSync(ROOT+'archive_write_journal.sql','utf8'));
 await db.exec(fs.readFileSync(ROOT+'archive_write_original_lookup.sql','utf8'));
 const routines=(await db.query(`select n.nspname as schema,p.proname as name,md5(pg_get_functiondef(p.oid)) as body_md5 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='rr_sandbox' and p.proname like 'archive_write_%' order by p.proname`)).rows;
 const version=(await db.query(`select current_setting('server_version_num') as v`)).rows[0].v;
 const pin={...structuredClone(managed),server_version_num:version,event_triggers:[],catalogue:{routines}};
 return {db,pin};
}
async function fresh(fn){const x=await fixture();try{return await fn(x);}finally{await x.db.close();}}
async function newObjects(db){return (await db.query(`select to_regclass('rr_sandbox.archive_dispatch_once_v2') as dispatch,to_regclass('rr_sandbox.backup_schedule_ticket_v1') as ticket`)).rows[0];}
test('one atomic closed install creates exactly two empty RLS tables and nine owner-only routines',()=>fresh(async({db,pin})=>{
 await db.exec(`set search_path=public,rr_sandbox`);
 await db.exec(build(pin));
 assert.equal((await db.query(`show search_path`)).rows[0].search_path,'public, rr_sandbox');
 assert.equal((await db.query(`select count(*)::int as n from rr_sandbox.archive_dispatch_once_v2`)).rows[0].n,0);
 assert.equal((await db.query(`select count(*)::int as n from rr_sandbox.backup_schedule_ticket_v1`)).rows[0].n,0);
 const rows=(await db.query(`select n.nspname||'.'||p.proname as name,has_function_privilege('anon',p.oid,'execute') as anon,has_function_privilege('authenticated',p.oid,'execute') as authed,has_function_privilege('service_role',p.oid,'execute') as service from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname||'.'||p.proname=any($1::text[])`,[NEW_FUNCTIONS])).rows;
 assert.equal(rows.length,9);assert.ok(rows.every(r=>!r.anon&&!r.authed&&!r.service));
 assert.deepEqual((await db.query(`select revision,archive_identity from rr_sandbox.archive_write_guard`)).rows,[{revision:0,archive_identity:null}]);
 assert.equal((await db.query(`select count(*)::int as n from rr_sandbox.archive_write_entries`)).rows[0].n,0);
}));
test('wrong branch metadata and private source identity are rejected without installation',()=>fresh(async({db,pin})=>{
 assert.throws(()=>build({...pin,sourceProject:'xkxolhgafjadpknsfqqw'}),/PIN_HELD/);
 await db.exec(`update auth.users set is_anonymous=true where id='${PRINCIPAL}'`);
 await assert.rejects(db.exec(build(pin)),/EXACT_TARGET_HELD/);
 assert.deepEqual(await newObjects(db),{dispatch:null,ticket:null});
}));
test('changed event inventory and legacy journal body both hold before new objects',()=>fresh(async({db,pin})=>{
 await assert.rejects(db.exec(build({...pin,event_triggers:[{name:'unobserved_event'}]})),/EVENT_INVENTORY_CHANGED/);
 await db.exec(`create or replace function rr_sandbox.archive_write_validate(p_identity text,p_key text,p_sha256 text,p_type text,p_size integer) returns void language plpgsql as $$begin return;end$$`);
 await assert.rejects(db.exec(build(pin)),/LEGACY_JOURNAL_CHANGED/);
 assert.deepEqual(await newObjects(db),{dispatch:null,ticket:null});
}));
test('unexpected custom default grants cause full rollback rather than retaining access',()=>fresh(async({db,pin})=>{
 await db.exec(`create role unexpected_reader; alter default privileges in schema public grant execute on functions to unexpected_reader`);
 await assert.rejects(db.exec(build(pin)),/OWNER_ONLY/);
 assert.deepEqual(await newObjects(db),{dispatch:null,ticket:null});
 assert.equal((await db.query(`select count(*)::int as n from rr_sandbox.archive_write_entries`)).rows[0].n,0);
}));
test('existing archive identity/history is not reset or silently migrated',()=>fresh(async({db,pin})=>{
 await db.exec(`update rr_sandbox.archive_write_guard set archive_identity='r2:fixture-account:fixture-archive',revision=revision+1 where singleton`);
 await assert.rejects(db.exec(build(pin)),/LEGACY_ARCHIVE_STATE_CHANGED/);
 assert.deepEqual(await newObjects(db),{dispatch:null,ticket:null});
 assert.equal((await db.query(`select revision from rr_sandbox.archive_write_guard`)).rows[0].revision,1);
}));
test('repeated install refuses existing objects while preserving the completed empty state',()=>fresh(async({db,pin})=>{
 await db.exec(build(pin));
 await assert.rejects(db.exec(build(pin)),/ALREADY_PRESENT/);
 assert.ok((await newObjects(db)).dispatch);assert.ok((await newObjects(db)).ticket);
 assert.equal((await db.query(`select count(*)::int as n from rr_sandbox.backup_schedule_ticket_v1`)).rows[0].n,0);
}));
test('qualified provider event identities remain stable under the install search path',()=>fresh(async({db,pin})=>{
 await db.exec(`create function public.observed_provider_event() returns event_trigger language plpgsql as $$begin return;end$$;create event trigger observed_provider_event on ddl_command_end execute function public.observed_provider_event()`);
 pin.event_triggers=(await db.query(eventsSQL)).rows[0].coalesce;
 assert.equal(pin.event_triggers[0].function,'public.observed_provider_event()');
 await db.exec(build(pin));
 assert.ok((await newObjects(db)).dispatch);
 assert.deepEqual((await db.query(eventsSQL)).rows[0].coalesce,pin.event_triggers);
}));
test('empty rollback removes only the new objects and retains the original journal',()=>fresh(async({db,pin})=>{
 await db.exec(build(pin));await db.exec(rollback());
 assert.deepEqual(await newObjects(db),{dispatch:null,ticket:null});
 assert.equal((await db.query(`select count(*)::int as n from rr_sandbox.archive_write_guard`)).rows[0].n,1);
 assert.equal((await db.query(`select count(*)::int as n from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='rr_sandbox' and p.proname like 'archive_write_%'`)).rows[0].n,6);
}));
test('global inherited maintenance access holds atomically even without an explicit object ACL',()=>fresh(async({db,pin})=>{
 await db.exec(`grant pg_maintain to service_role`);
 await assert.rejects(db.exec(build(pin)),/EFFECTIVE_ACL_HELD|EFFECTIVE_PRIVILEGE_HELD/);
 assert.deepEqual(await newObjects(db),{dispatch:null,ticket:null});
}));

-- UNINSTALLED SOURCE PROPOSAL. Requires unchanged archive_write_journal.sql.
-- A new claim reserves dispatch atomically; gateway consumes it once. Legacy
-- unknown claims are NEVER backfilled. No verified writer, rebind or reset.
BEGIN;
CREATE TABLE rr_sandbox.archive_dispatch_once_v2 (
 object_key text PRIMARY KEY REFERENCES rr_sandbox.archive_write_entries(object_key),
 attempt_id uuid NOT NULL UNIQUE,
 request_sha256 text NOT NULL CHECK(request_sha256 ~ '^[a-f0-9]{64}$'),
 lease_sha256 text NOT NULL CHECK(lease_sha256 ~ '^[a-f0-9]{64}$'),
 source_path_sha256 text NOT NULL CHECK(source_path_sha256 ~ '^[a-f0-9]{64}$'),
 snapshot_id uuid NOT NULL,
 state text NOT NULL DEFAULT 'reserved' CHECK(state IN('reserved','consumed')),
 reserved_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 first_gateway_nonce uuid UNIQUE,
 consumed_at timestamptz,
 CHECK((state='consumed')=(first_gateway_nonce IS NOT NULL AND consumed_at IS NOT NULL)),
 CHECK(consumed_at IS NULL OR consumed_at>=reserved_at)
);
ALTER TABLE rr_sandbox.archive_dispatch_once_v2 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON rr_sandbox.archive_dispatch_once_v2 FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION rr_sandbox.archive_dispatch_no_reset_v2() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'Original archive dispatch cannot reset'; END IF;
 IF ROW(NEW.object_key,NEW.attempt_id,NEW.request_sha256,NEW.lease_sha256,NEW.source_path_sha256,NEW.snapshot_id,NEW.reserved_at)
  IS DISTINCT FROM ROW(OLD.object_key,OLD.attempt_id,OLD.request_sha256,OLD.lease_sha256,OLD.source_path_sha256,OLD.snapshot_id,OLD.reserved_at)
  OR OLD.state<>'reserved' OR NEW.state<>'consumed' OR OLD.first_gateway_nonce IS NOT NULL OR OLD.consumed_at IS NOT NULL
  OR NEW.first_gateway_nonce IS NULL OR NEW.first_gateway_nonce='00000000-0000-0000-0000-000000000000' OR NEW.consumed_at IS NULL
 THEN RAISE EXCEPTION 'Original archive dispatch cannot reset'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER archive_dispatch_immutable_v2 BEFORE UPDATE OR DELETE ON rr_sandbox.archive_dispatch_once_v2 FOR EACH ROW EXECUTE FUNCTION rr_sandbox.archive_dispatch_no_reset_v2();
CREATE TRIGGER archive_dispatch_no_truncate_v2 BEFORE TRUNCATE ON rr_sandbox.archive_dispatch_once_v2 FOR EACH STATEMENT EXECUTE FUNCTION rr_sandbox.archive_dispatch_no_reset_v2();
CREATE FUNCTION rr_sandbox.archive_dispatch_context_v2(p_identity text,p_key text,p_request text,p_lease text,p_source text,p_snapshot uuid) RETURNS void
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
BEGIN
 IF p_identity IS DISTINCT FROM 'r2:7a3ed4f82692abebebc6447e5f5e217c:rack-relic-private-photo-archive' OR
  p_snapshot IS NULL OR p_snapshot='00000000-0000-0000-0000-000000000000' OR split_part(p_key,'/',3) IS DISTINCT FROM p_snapshot::text OR
  p_request IS NULL OR p_request !~ '^[a-f0-9]{64}$' OR p_request=repeat('0',64) OR
  p_lease IS NULL OR p_lease !~ '^[a-f0-9]{64}$' OR p_lease=repeat('0',64) OR
  p_source IS NULL OR p_source !~ '^[a-f0-9]{64}$' OR p_source=repeat('0',64)
 THEN RAISE EXCEPTION 'Original dispatch context required'; END IF;
END $$;
CREATE FUNCTION rr_sandbox.archive_claim_for_dispatch_v2(
 p_identity text,p_key text,p_sha256 text,p_type text,p_size integer,
 p_request_sha256 text,p_lease_sha256 text,p_source_path_sha256 text,p_snapshot uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE q jsonb; prior rr_sandbox.archive_dispatch_once_v2;
BEGIN
 PERFORM rr_sandbox.archive_dispatch_context_v2(p_identity,p_key,p_request_sha256,p_lease_sha256,p_source_path_sha256,p_snapshot);
 q:=rr_sandbox.archive_write_claim(p_identity,p_key,p_sha256,p_type,p_size);
 IF (q->>'sendAllowed')::boolean THEN
  INSERT INTO rr_sandbox.archive_dispatch_once_v2(object_key,attempt_id,request_sha256,lease_sha256,source_path_sha256,snapshot_id)
   VALUES(p_key,(q->>'attemptId')::uuid,p_request_sha256,p_lease_sha256,p_source_path_sha256,p_snapshot);
 END IF;
 SELECT * INTO prior FROM rr_sandbox.archive_dispatch_once_v2 WHERE object_key=p_key;
 IF FOUND AND ROW(prior.attempt_id,prior.request_sha256,prior.lease_sha256,prior.source_path_sha256,prior.snapshot_id)
  IS DISTINCT FROM ROW((q->>'attemptId')::uuid,p_request_sha256,p_lease_sha256,p_source_path_sha256,p_snapshot)
 THEN RAISE EXCEPTION 'Original dispatch window conflict'; END IF;
 RETURN jsonb_build_object('version','rr-window-original-claim-v2','original',q,'dispatchReservationState',coalesce(prior.state,'unreserved'),'releaseEnabled',false);
END $$;
CREATE FUNCTION rr_sandbox.archive_dispatch_consume_v2(
 p_identity text,p_key text,p_sha256 text,p_type text,p_size integer,p_attempt uuid,
 p_request_sha256 text,p_lease_sha256 text,p_source_path_sha256 text,p_snapshot uuid,p_gateway_nonce uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE q rr_sandbox.archive_write_entries; prior rr_sandbox.archive_dispatch_once_v2; allowed boolean:=false;
BEGIN
 PERFORM rr_sandbox.archive_write_validate(p_identity,p_key,p_sha256,p_type,p_size);
 PERFORM rr_sandbox.archive_dispatch_context_v2(p_identity,p_key,p_request_sha256,p_lease_sha256,p_source_path_sha256,p_snapshot);
 IF p_attempt IS NULL OR p_attempt='00000000-0000-0000-0000-000000000000' OR
  p_gateway_nonce IS NULL OR p_gateway_nonce='00000000-0000-0000-0000-000000000000'
 THEN RAISE EXCEPTION 'Original dispatch reference required'; END IF;
 SELECT * INTO q FROM rr_sandbox.archive_write_entries WHERE object_key=p_key FOR UPDATE;
 IF NOT FOUND OR ROW(q.archive_identity,q.sha256,q.content_type,q.byte_count,q.attempt_id)
  IS DISTINCT FROM ROW(p_identity,p_sha256,p_type,p_size,p_attempt)
 THEN RAISE EXCEPTION 'Original archive claim required'; END IF;
 SELECT * INTO prior FROM rr_sandbox.archive_dispatch_once_v2 WHERE object_key=p_key FOR UPDATE;
 IF NOT FOUND OR ROW(prior.attempt_id,prior.request_sha256,prior.lease_sha256,prior.source_path_sha256,prior.snapshot_id)
  IS DISTINCT FROM ROW(p_attempt,p_request_sha256,p_lease_sha256,p_source_path_sha256,p_snapshot)
 THEN RAISE EXCEPTION 'Original dispatch reservation required'; END IF;
 IF prior.state='reserved' AND q.outcome='unknown' THEN
  UPDATE rr_sandbox.archive_dispatch_once_v2 SET state='consumed',first_gateway_nonce=p_gateway_nonce,consumed_at=greatest(reserved_at,clock_timestamp()) WHERE object_key=p_key;
  allowed:=true;
 END IF;
 -- Lost replies or provider timeouts never reopen this authorization. A new
 -- isolate/nonce gets false; a new request/lease cannot rebind its reservation.
 RETURN jsonb_build_object('version','rr-window-original-dispatch-v2','test',true,'sourceProjectRef','tzymapahsfiyhgilsmxl',
  'identity',p_identity,'key',p_key,'sha256',p_sha256,'contentType',p_type,'size',p_size,'attemptId',p_attempt,
  'requestSha256',p_request_sha256,'leaseSha256',p_lease_sha256,'sourcePathSha256',p_source_path_sha256,'snapshotId',p_snapshot,
  'gatewayNonce',p_gateway_nonce,'sendAllowed',allowed,'releaseEnabled',false);
END $$;
