CREATE FUNCTION rr_sandbox.archive_write_no_reset() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'Archive journal cannot reset'; END IF;
 IF TG_TABLE_NAME='archive_write_guard' THEN
  IF TG_OP='INSERT' OR NEW.revision<>OLD.revision+1 OR
   (OLD.archive_identity IS NOT NULL AND NEW.archive_identity IS DISTINCT FROM OLD.archive_identity) OR
   NEW.archive_identity IS NULL OR NEW.singleton IS DISTINCT FROM OLD.singleton
  THEN RAISE EXCEPTION 'Archive identity cannot reset'; END IF;
 ELSE
  IF TG_OP='INSERT' THEN
   IF NEW.outcome<>'unknown' OR NEW.verified_at IS NOT NULL THEN RAISE EXCEPTION 'Original unknown claim required'; END IF;
  ELSIF ROW(NEW.object_key,NEW.archive_identity,NEW.sha256,NEW.content_type,NEW.byte_count,NEW.attempt_id,NEW.claimed_at)
    IS DISTINCT FROM ROW(OLD.object_key,OLD.archive_identity,OLD.sha256,OLD.content_type,OLD.byte_count,OLD.attempt_id,OLD.claimed_at)
    OR OLD.outcome<>'unknown' OR NEW.outcome<>'verified' OR NEW.verified_at IS NULL
  THEN RAISE EXCEPTION 'Archive binding and verified history are immutable'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER archive_guard_immutable BEFORE INSERT OR UPDATE OR DELETE ON rr_sandbox.archive_write_guard FOR EACH ROW EXECUTE FUNCTION rr_sandbox.archive_write_no_reset();
CREATE TRIGGER archive_guard_no_truncate BEFORE TRUNCATE ON rr_sandbox.archive_write_guard FOR EACH STATEMENT EXECUTE FUNCTION rr_sandbox.archive_write_no_reset();
CREATE TRIGGER archive_entries_immutable BEFORE INSERT OR UPDATE OR DELETE ON rr_sandbox.archive_write_entries FOR EACH ROW EXECUTE FUNCTION rr_sandbox.archive_write_no_reset();
CREATE TRIGGER archive_entries_no_truncate BEFORE TRUNCATE ON rr_sandbox.archive_write_entries FOR EACH STATEMENT EXECUTE FUNCTION rr_sandbox.archive_write_no_reset();

CREATE FUNCTION rr_sandbox.archive_write_validate(p_identity text,p_key text,p_sha256 text,p_type text,p_size integer) RETURNS void
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
BEGIN
 IF p_identity IS NULL OR p_identity !~ '^r2:[a-z0-9_-]{3,100}:[a-z0-9_-]{3,100}$' OR p_key IS NULL OR
  p_key !~ '^snapshots/b3da65e2d3ec11eee93fa81c8e8f8fe2/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/(manifest[.]json|objects/[0-9a-f]{64})$' OR
  p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$' OR p_type IS NULL OR p_type NOT IN('application/json','image/jpeg','image/png','image/webp') OR
  p_size IS NULL OR p_size NOT BETWEEN 1 AND 2097152 OR (right(p_key,14)='/manifest.json')<>(p_type='application/json') OR
  (right(p_key,14)<>'/manifest.json' AND right(p_key,64)<>p_sha256)
 THEN RAISE EXCEPTION 'Invalid archive binding'; END IF;
END $$;
CREATE FUNCTION rr_sandbox.archive_write_projection(q rr_sandbox.archive_write_entries,p_send boolean) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('test',true,'sourceProjectRef','tzymapahsfiyhgilsmxl','identity',q.archive_identity,'key',q.object_key,
  'sha256',q.sha256,'contentType',q.content_type,'size',q.byte_count,'attemptId',q.attempt_id,'outcome',q.outcome,'sendAllowed',p_send,'releaseEnabled',false)
$$;
CREATE FUNCTION rr_sandbox.archive_write_claim(p_identity text,p_key text,p_sha256 text,p_type text,p_size integer) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE g rr_sandbox.archive_write_guard; q rr_sandbox.archive_write_entries;
BEGIN
 PERFORM rr_sandbox.archive_write_validate(p_identity,p_key,p_sha256,p_type,p_size);
 SELECT * INTO STRICT g FROM rr_sandbox.archive_write_guard WHERE singleton FOR UPDATE;
 IF g.archive_identity IS NOT NULL AND g.archive_identity<>p_identity THEN RAISE EXCEPTION 'Archive identity conflict'; END IF;
 SELECT * INTO q FROM rr_sandbox.archive_write_entries WHERE object_key=p_key;
 IF FOUND THEN
  IF ROW(q.archive_identity,q.sha256,q.content_type,q.byte_count) IS DISTINCT FROM ROW(p_identity,p_sha256,p_type,p_size)
   THEN RAISE EXCEPTION 'Archive binding conflict'; END IF;
  RETURN rr_sandbox.archive_write_projection(q,false);
 END IF;
 IF EXISTS(SELECT 1 FROM rr_sandbox.archive_write_entries WHERE outcome='unknown') THEN RAISE EXCEPTION 'Unresolved original archive write'; END IF;
 UPDATE rr_sandbox.archive_write_guard SET archive_identity=p_identity,revision=revision+1 WHERE singleton;
 INSERT INTO rr_sandbox.archive_write_entries(object_key,archive_identity,sha256,content_type,byte_count)
  VALUES(p_key,p_identity,p_sha256,p_type,p_size) RETURNING * INTO q;
 RETURN rr_sandbox.archive_write_projection(q,true);
END $$;
CREATE FUNCTION rr_sandbox.archive_write_record(p_identity text,p_key text,p_sha256 text,p_type text,p_size integer,p_attempt uuid,p_outcome text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
