  THEN RAISE EXCEPTION 'Original archive reference required'; END IF;
 SELECT * INTO STRICT g FROM rr_sandbox.archive_write_guard WHERE singleton FOR UPDATE;
 SELECT * INTO q FROM rr_sandbox.archive_write_entries WHERE object_key=p_key FOR UPDATE;
 IF NOT FOUND OR g.archive_identity IS DISTINCT FROM p_identity OR
  ROW(q.archive_identity,q.sha256,q.content_type,q.byte_count,q.attempt_id) IS DISTINCT FROM ROW(p_identity,p_sha256,p_type,p_size,p_attempt)
  THEN RAISE EXCEPTION 'Original archive reference required'; END IF;
